def compress_sequence(s: str) -> str:
    if not s:
        return ''
    result = []
    current_char = s[0]
    count = 1
    for c in s[1:]:
        if c == current_char:
            count += 1
        else:
            result.append(f'{current_char}{count}')
            current_char = c
            count = 1
    # Append the last group
    result.append(f'{current_char}{count}')
    return ''.join(result)
